  &DefaultButton;




function dir$sysgroupinfo(p){
  this.constructor(p);
}
dir$sysgroupinfo.prototype = new DirEvent();
dir$sysgroupinfo.prototype.afterInit = function(){
  var p = this._dir;
}
dir$sysgroupinfo.prototype.beforeButtonDialogClick = function(id){
  var p = this._dir;
  return true;
}








if @action = 'NEW' and @@admin = 0 begin
  select N'$AdminAccess' as message
  return
end
select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table
drop table #@@table







select 'p.options._os = ''@@os|@@userId|@@userName|@@lan'';' as script --as message la dừng show form







declare @gname varchar(64)
select @gname = groupname from @@table where group_id = @group_id
if @groupname <> @gname begin
  if exists(select 1 from @@table where groupname = @groupname and group_id <> @group_id) or exists(select 1 from sysuserinfo where username = @groupname) begin
    select '$codeExistsNewMsg' as message, 'groupname' as field
    return
  end
end







if exists(select 1 from @@table a where groupname = @groupname) or exists(select 1 from sysuserinfo where username = @groupname) begin
  select '$codeExistsNewMsg' as message, 'groupname' as field
  return
end
select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId

--select @group_id = max(group_id) + 1 from @@table
select @group_id = max(id) + 1 from (select max(user_id) as id from sysuserinfo union all select max(group_id) as id from sysgroupinfo) a
if @group_id is null select @group_id = 1







select '' as message, @group_id as [#group_id]
